function [gh] = igrf_gh(dy)
%IGRF_GH  The Gauss coefficients at a decimal year: straight-line between the two epochs around it (IGRF-14's own definition of
%   its coefficients between epochs). The table is env_igrf14_coefficients': 27 epochs, 1900.0 to 2025.0 and 2030.0, which
%   is 2025.0 plus five years of the 2025-30 secular variation, so the 2025-30 interval is interpolated, not extrapolated.
%   dy: real[1] (passed a plain number)
%   returns gh: real[1][195] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    gh = zeros(195, 1);
    D__IGRF14_GH = asils.models.igrf14coeffs.IGRF14_GH();
    D__IGRF14_YEAR = asils.models.igrf14coeffs.IGRF14_YEAR();
    i = 0;
    t__516 = ((0):((26) - 1)).';
    for ii = t__516(logical((D__IGRF14_YEAR(((t__516 + 1)) + 1) <= dy))).'
        i = (ii + 1);
    end
    if (i >= 26)
        i = 25;
    end
    f = ((dy - D__IGRF14_YEAR((i) + 1)) / (D__IGRF14_YEAR(((i + 1)) + 1) - D__IGRF14_YEAR((i) + 1)));
    k = ((0):((195) - 1)).';
    gh((k) + 1) = ((D__IGRF14_GH((i) + 1, (k) + 1)).' + (((D__IGRF14_GH(((i + 1)) + 1, (k) + 1)).' - (D__IGRF14_GH((i) + 1, (k) + 1)).') .* f));
end
